if mibBuilder.loadTexts: dsx3LineNum.setDescription('This object is the identifier of a DS3/E3\n        Interface on a managed device.\n\n        The range supported depends upon the type of\n        the card(controller card, service module).\n\n        For 1 port Card :  Range is 1..1\n           Example : CESM-T3E3\n\n        For 2 Port Card :  Range is 1..2\n           Example : PXM1-2T3E3.\n\n        For 3 Port Card : Range is 1..3\n           Example: SRM-3T3')
cwDsx3LineType = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 2), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6))).clone(namedValues=NamedValues(("dsx3CbitParity", 1), ("g832-g804", 2), ("dsx3M23", 3), ("g751", 4), ("dsx3Unframed", 5), ("e3Unframed", 6)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cwDsx3LineType.setStatus('current')
if mibBuilder.loadTexts: cwDsx3LineType.setDescription('This variable indicates the variety of DS3 C-bit\n        or E3 application implementing this interface.\n        The type of interface affects the interpretation\n        of the usage and error statistics. The rate of DS3\n        is 44.736 Mbps and E3 is 34.368 Mbps.\n\n        The values, in sequence, describe:\n\n        TITLE:                     SPECIFICATION:\n\n        dsx3CbitParity            ANSI T1.107a-1990   [9a]\n        g832-g804                 ITU-T  G.832, G.804\n        dsx3M23                   ANSI T1.107-1988    [9]\n        g751                      ITU-T G.751\n        CESM-T3 supports only ds3Unframed linetype.\n        CESM-E3 supports only e3Unframed linetype.')
cwDsx3LineCoding = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 3), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("dsx3B3ZS", 1), ("e3HDB3", 2)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cwDsx3LineCoding.setStatus('current')
if mibBuilder.loadTexts: cwDsx3LineCoding.setDescription('This variable describes the variety of Zero Code\n        Suppression used on this interface, which in turn\n        affects a number of its characteristics.\n\n        dsx3B3ZS and e3HDB3 refer to the use of specified\n        patterns of normal bits and bipolar violations\n        which are used to replace sequences of zero bits\n        of a specified length.\n\n        dsx3B3ZS(1) : Bipolar 3-Zero Substitution(B3ZS) suppression.\n        e3HDB3  (2) : High-Density Bipolar 3(HDB3) suppression.')
