if mibBuilder.loadTexts: dsx3LineAIScBitsCheck.setStatus('current')
if mibBuilder.loadTexts: dsx3LineAIScBitsCheck.setDescription('If check C-Bits options is chosen then AIS is declared\n        when 1010 pattern is found and C-Bits are all zero. \n        In the other case an AIS condition is declared when the\n        AIS pattern 1010... is detected irrespective of the state\n        of the C Bits.\n        This object does not apply to the E3 interface.\n        The value notApplicable(3) is used in case of interfaces\n        where this object is not applicable.\n\n        This object is not applicable for CESM-T3/E3.')
dsx3LineLoopbackCommand = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 7), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("dsx3NoLoop", 1), ("dsx3RemoteLineLoop", 2), ("dsx3LocalLineLoop", 3), ("dsx3InbndLocalLoopback", 4)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: dsx3LineLoopbackCommand.setStatus('current')
if mibBuilder.loadTexts: dsx3LineLoopbackCommand.setDescription("This variable represents the loopback configuration\n        of the DS3/E3 interface.\n        The values mean:\n            dsx3NoLoop\n                Not in the loopback state.  A device that is\n                not capable of performing a loopback on\n                the interface shall always return this as\n                it's value.\n            dsx3RemoteLineLoop\n                Near End loops back Remote data\n            dsx3LocalLineLoop\n                Near End loops back Local data(outbound).\n            dsx3InboundLoopback\n                Near End in bound loopback Local data(inbound).")
dsx3LineRcvFEACValidation = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 8), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3))).clone(namedValues=NamedValues(("fFEACCodes4Of5", 1), ("fFEACCodes8Of10", 2), ("fFEACCodesDisable", 3)))).setMaxAccess("readwrite")
