if mibBuilder.loadTexts: dsx3LineRcvFEACValidation.setDescription('This entry specifies the FEAC code validation criteria.\n        fFEACCodes4Of5(1) : a valid FEAC code is declared if\n                            4 of 5 codes match.\n        fFEACCodes8Of10(2): a valid FEAC code is declared if \n                            8 of 10 codes match.\n\n        fFEACCodesDisable(3) : Do not respond to any valid FEAC code.\n        This object is not applicable to E3 interface.\n\n        This object is not supported in CESM-T3/E3.')
dsx3LineXmtFEACCode = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 9), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6))).clone(namedValues=NamedValues(("dsx3SendNoCode", 1), ("dsx3SendLineCode", 2), ("dsx3SendPayloadCode", 3), ("dsx3SendResetCode", 4), ("dsx3SendDS1LoopCode", 5), ("dsx3SendTestPattern", 6)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: dsx3LineXmtFEACCode.setStatus('current')
if mibBuilder.loadTexts: dsx3LineXmtFEACCode.setDescription('This variable indicates what bit-oriented code to transmit\n        over the far-end alarm and control (FEAC) channel.\n\n        The values mean:\n\n        dsx3SendNoCode\n            sending looped or normal data\n        dsx3SendLineCode\n            sending a request for a line loopback\n        dsx3SendPayloadCode\n            sending a request for a payload loopback\n        (i.e., all DS1/E1s in a DS3/E3 frame)\n        dsx3SendResetCode\n            sending a loopback deactivation request.\n        dsx3SendDS1LoopCode\n            sending a request to put part of DS1/E1 within\n            T3/E3 respectively into loopback.\n        dsx3SendTestPattern\n            sending a test pattern.\n        This object is not applicable for CESM-T3/E3')
dsx3LineBERTEnable = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 10), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("disabled", 1), ("enabled", 2)))).setMaxAccess("readwrite")
