if mibBuilder.loadTexts: dsx3TrailTraceOption.setReference('ITU-T G.832')
if mibBuilder.loadTexts: dsx3TrailTraceOption.setStatus('current')
if mibBuilder.loadTexts: dsx3TrailTraceOption.setDescription('This object is used for enabling/disabling \n        G.832 Trail Trace. The trail trace is used to \n        repetitively transmit a trail access point identifier\n        so that a trail receiving terminal can verify its \n        continued connection to the intended transmitter.\n        It uses a 16-byte numbering format (see Rec E.164).\n        The first byte of the string is a frame start marker \n        and includes the result of a CRC-7 calculation over \n        the previous frame. \n\n        The value of this object is set to disable(1) in case\n        of cards where this feature is not supported.\n\n        This object is not applicable for FRSM-VHS and\n        CESM-T3/E3.')
dsx3TxTrailTrace = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 15), DisplayString().subtype(subtypeSpec=ValueSizeConstraint(1, 15))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: dsx3TxTrailTrace.setReference('ITU-T G.832')
if mibBuilder.loadTexts: dsx3TxTrailTrace.setStatus('current')
if mibBuilder.loadTexts: dsx3TxTrailTrace.setDescription('This object is used for specifying the \n        data to be used for G.832 Trail Trace ID/String.\n        This object is applicable only for E3 interfaces\n        with G.832 framing.\n\n        The trail trace ID is a 16 octet field that\n        contains 1 octet of CRC-7(first octet) and 15\n        octets of data.\n\n        The CRC-7 is automatically calculated by the\n        system(card supporting this feature).\n        \n        The format of the value is:\n          Frame Start Marker Error(HEX): CRC-7\n          Bytes 2-6   (ASCII) [Byte 1-5 of this object]\n          Bytes 7-11  (ASCII) [Byte 6-10 of this object]\n          Bytes 12-16 (ASCII) [Byte 11-15 of this object]\n \n       This object is not applicable for FRSM-VHS and\n       CESM-T3/E3.')
dsx3RxTrailTrace = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 16), DisplayString().subtype(subtypeSpec=ValueSizeConstraint(1, 15))).setMaxAccess("readonly")
if mibBuilder.loadTexts: dsx3RxTrailTrace.setReference('ITU-T G.832')
if mibBuilder.loadTexts: dsx3RxTrailTrace.setStatus('current')
if mibBuilder.loadTexts: dsx3RxTrailTrace.setDescription('Received G.832 Trail Trace string. \n        The format of the value is:\n          First byte indicates CRC-7(frame start marker).\n          Bytes 2-6   (ASCII) [Byte 1-5 of this object]\n          Bytes 7-11  (ASCII) [Byte 6-10 of this object]\n          Bytes 12-16 (ASCII) [Byte 11-15 of this object]\n          The value of all zeroes indicates bad CRC-7.\n\n       This object is not applicable for FRSM-VHS and\n       CESM-T3/E3.')
dsx3TxTimingMarker = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 1, 1, 1, 17), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("traceable", 1), ("untraceable", 2)))).setMaxAccess("readwrite")
