dsx3FEAlarmUpCount = MibTableColumn((1, 3, 6, 1, 4, 1, 351, 110, 4, 4, 1, 2, 1, 1, 6), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 2147483647))).setMaxAccess("readwrite")
